package com.hack23.cia.model.internal.application.data.impl;

import java.io.Serializable;
import java.math.BigDecimal;
import java.time.LocalDate;
import javax.persistence.*;
import org.hibernate.annotations.Immutable;
import lombok.Data;
import lombok.EqualsAndHashCode;

/**
 * JPA Entity for view_riksdagen_party_decision_flow database view.
 * 
 * Provides party-level decision flow analysis with approval rates,
 * decision patterns, and temporal trends.
 * 
 * Intelligence Value: ⭐⭐⭐⭐⭐ VERY HIGH
 * - Party decision effectiveness tracking
 * - Coalition alignment analysis
 * - Legislative productivity metrics
 * 
 * Related Issue: Hack23/cia#7918
 * Related Documentation: DATABASE_VIEW_INTELLIGENCE_CATALOG.md
 * 
 * @author intelligence-operative
 * @since v1.35 (Decision Intelligence)
 */
@Entity
@Immutable
@Table(name = "view_riksdagen_party_decision_flow")
@IdClass(ViewRiksdagenPartyDecisionFlow.ViewDecisionFlowId.class)
@Data
@EqualsAndHashCode(of = {"party", "committee", "decisionType", "decisionMonth"})
public class ViewRiksdagenPartyDecisionFlow implements Serializable {

    private static final long serialVersionUID = 1L;

    @Id
    @Column(name = "party", nullable = false)
    private String party;

    @Id
    @Column(name = "committee", nullable = false)
    private String committee;

    @Id
    @Column(name = "decision_type", nullable = false)
    private String decisionType;

    @Id
    @Column(name = "decision_month", nullable = false)
    private LocalDate decisionMonth;

    @Column(name = "decision_year", nullable = false)
    private Integer decisionYear;

    @Column(name = "total_proposals", nullable = false)
    private Long totalProposals;

    @Column(name = "approved_proposals", nullable = false)
    private Long approvedProposals;

    @Column(name = "rejected_proposals", nullable = false)
    private Long rejectedProposals;

    @Column(name = "approval_rate", precision = 5, scale = 2)
    private BigDecimal approvalRate;

    /**
     * Composite primary key for decision flow view.
     */
    @Data
    public static class ViewDecisionFlowId implements Serializable {
        private static final long serialVersionUID = 1L;
        private String party;
        private String committee;
        private String decisionType;
        private LocalDate decisionMonth;
    }
}
```

